100	    /**
101	      * English implementation note.
102	      * English implementation note.
103	      * English implementation note.
104	      * English implementation note.
105	     */
106	    public UserDTO authenticate(String email, String password) {
107	        validateCredentialFormat(email, password);
108	
109	        User user = userRegistry.findUserByEmail(email);
110	
111	        if (user == null) {
112	            throw new SecurityException("Invalid credentials or user does not exist.");
113	        }
114	        if (user.isBloccato()) {
115	            throw new SecurityException("Account locked after too many failed attempts. Try again in "
116	                    + MINUTI_BLOCCO + " minutes.");
117	        }
118	
119	        if (!verifyCredentials(user, password)) {
120	            incrementaTentativi(user);
121	            boolean appenaBloccato = user.getFailedAttempts() >= MAX_TENTATIVI;
122	            if (appenaBloccato) {
123	                bloccaAccountTemporaneamente(user, MINUTI_BLOCCO);
124	            }
125	            userRegistry.update(user);
126	            if (appenaBloccato) {
127	                throw new SecurityException("Invalid credentials. Account locked for " + MINUTI_BLOCCO
128	                        + " minutes after too many failed attempts.");
129	            }
130	            throw new SecurityException("Invalid credentials or user does not exist.");
131	        }
132	
133	        resetTentativi(user);
134	        userRegistry.update(user);
135	        return toDTO(user);
136	    }
