139	      * English implementation note.
140	      * English implementation note.
141	      * English implementation note.
142	     */
143	    private void validateCredentialFormat(String email, String password) {
144	        require(email != null && !email.isEmpty(), "Email is required.");
145	        require(isEmailWellFormed(email), "Invalid email format.");
146	        require(password != null && !password.isEmpty(), "Password is required.");
147	        require(password.length() >= 8, "Password must contain at least 8 characters.");
148	        require(password.length() <= 32, "Invalid password format.");
149	    }
