168	    // ------------------------------------------------------------------ helper privati
169	    private boolean isValidRole(String role) {
170	        return "Student".equalsIgnoreCase(role) || "Librarian".equalsIgnoreCase(role);
171	    }
172	
173	    private void validateStudent(String name, String surname, String email, String studentNumber) {
174	        validateNameAndSurname(name, surname);
175	        validateEmail(email);
176	        validateIdentifier(studentNumber, "studentNumber");
177	        if (!studentNumber.matches(REGEX_STUDENT_NUMBER)) {
178	            throw new IllegalArgumentException(
179	                    "Unrecognized identifier format: the student ID must be an uppercase letter followed by 8 digits (e.g. N86001234).");
180	        }
181	    }
182	
183	    private void validateLibrarian(String name, String surname, String email, String code) {
184	        validateNameAndSurname(name, surname);
185	        validateEmail(email);
186	        validateIdentifier(code, "code identifier");
187	    }
188	
189	    private void validateNameAndSurname(String name, String surname) {
190	        if (!name.matches("\\p{L}{1,20}")) {
191	            throw new IllegalArgumentException("Invalid first-name format (letters only, max 20 characters).");
192	        }
193	        if (surname == null || surname.isEmpty()) {
194	            throw new IllegalArgumentException("Last name is required.");
195	        }
196	        if (!surname.matches("\\p{L}{1,20}")) {
197	            throw new IllegalArgumentException("Invalid last-name format (letters only, max 20 characters).");
198	        }
199	    }
200	
201	    private void validateEmail(String email) {
202	        if (email == null || email.isEmpty()) {
203	            throw new IllegalArgumentException("Email is required.");
204	        }
205	        // English implementation note.
206	        if (email.length() >= 255) {
207	            throw new IllegalArgumentException("Email is too long (max 255 characters).");
208	        }
209	        if (!isEmailWellFormed(email)) {
210	            throw new IllegalArgumentException("Invalid email format.");
211	        }
212	    }
213	
214	    private void validateIdentifier(String identifier, String label) {
215	        if (identifier == null || identifier.isEmpty()) {
216	            throw new IllegalArgumentException("Identifier is required.");
217	        }
218	        if (!identifier.matches("[A-Za-z0-9]+")) {
219	            throw new IllegalArgumentException("Invalid " + label + " format.");
220	        }
221	    }
222	
223	    private boolean verifyCredentials(User user, String password) {
224	        return password != null && password.equals(user.getPassword());
225	    }
226	
227	    private void incrementaTentativi(User user) {
228	        user.setFailedAttempts(user.getFailedAttempts() + 1);
229	    }
230	
231	    private void bloccaAccountTemporaneamente(User user, int durataMinuti) {
232	        user.setLockedUntilA(LocalDateTime.now(ZoneId.of("Europe/Rome")).plusMinutes(durataMinuti));
233	        user.setFailedAttempts(0);
234	    }
235	
236	    private void resetTentativi(User user) {
237	        user.setFailedAttempts(0);
238	        user.setLockedUntilA(null);
239	    }
240	
241	    /** English implementation note. */
242	    private UserDTO toDTO(User user) {
243	        UserDTO dto = new UserDTO();
244	        dto.setId(user.getId());
245	        dto.setName(user.getName());
246	        dto.setSurname(user.getSurname());
247	        dto.setInstitutionalEmail(user.getInstitutionalEmail());
248	        if (user instanceof Student s) {
249	            dto.setRole("Student");
250	            dto.setIdentifier(s.getStudentNumber());
251	            dto.setTotalVisitCount(s.getTotalVisitCount());
252	        } else if (user instanceof Librarian b) {
253	            dto.setRole("Librarian");
254	            dto.setIdentifier(b.getInternalIdentifierCode());
255	        }
256	        return dto;
257	    }
258	}
