package it.unina.reservations.controller;

import it.unina.reservations.database.JpaUtil;
import it.unina.reservations.dto.UserDTO;
import jakarta.persistence.EntityManager;
import jakarta.persistence.EntityTransaction;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

@DisplayName("Test Suite - User Registration")
class RegistrationTest {

    private LibraryFacade libraryFacade;
    private EntityManager em;


    @BeforeEach
    void setUp() {
        libraryFacade = LibraryFacade.getInstance();
        em = JpaUtil.getInstance().getEntityManager();

        // English implementation note.
        svuotaDatebase(em);
    }

    @AfterEach
    void tearDown() {
        svuotaDatebase(em);
    }
    private void svuotaDatebase(EntityManager em) {
        EntityTransaction transaction = em.getTransaction();
        try {
            if (!transaction.isActive()) {
                transaction.begin();
            }

            // English implementation note.
            em.createQuery("DELETE FROM Reservation").executeUpdate();
            em.createQuery("DELETE FROM User").executeUpdate();


            transaction.commit();
        } catch (Exception e) {
            if (transaction.isActive()) transaction.rollback();
            throw new RuntimeException("Error while cleaning the test database: " + e.getMessage(), e);
        }
    }

    @Test
    @DisplayName("TC1: Student registration with valid date")
    void registerStudentValido_Succeeds() {
        // Arrange
        String email = "a.rossi.tc1@studenti.unina.it"; // English implementation note.
        String studentNumber = "N86001001"; // English implementation note.

        // Act
        UserDTO result = libraryFacade.register(
                "Student", "Michele", "Rossi", email, "Password123!", studentNumber
        );

        // Assert
        assertNotNull(result, "The returned DTO must not be null");
        assertEquals("Student", result.getRole());
        assertEquals("Michele", result.getName());
        assertEquals(email, result.getInstitutionalEmail());
        assertEquals(studentNumber, result.getIdentifier());
    }

    @Test
    @DisplayName("TC2: Librarian registration with valid date")
    void registerLibrarianValido_Succeeds() {
        String email = "m.esposito.tc2@unina.it";
        String code = "BIBLIO001";

        UserDTO result = libraryFacade.register(
                "Librarian", "Maria", "Esposito", email, "SecurPass2026!", code
        );

        assertNotNull(result);
        assertEquals("Librarian", result.getRole());
        assertEquals(code, result.getIdentifier());
    }

    // ==========================================
    // English implementation note.
    // ==========================================
